```c
#include <stdio.h>

void shift(int *p, int n) {
    for (int i = n - 1; i > 0; i--) {
        p[i] = p[i - 1];
    }
}

int main(void) {
    int a[6] = {3, 1, 4, 1, 5, 9};
    int *q = &a[2];
    shift(q, 3);
    *(q + 2) += *a;
    int s = 0;
    for (int *r = a; r < a + 6; r += 2) {
        s += *r;
    }
    printf("%d %d\n", a[3], s);
    return 0;
}
```

